import asyncio

# === 1. try/except/else/finally 四子句时机 ===
def divide(a, b):
    try:
        result = a / b
    except ZeroDivisionError as e:
        # 显式异常链：转换类型但保留根因
        raise ValueError("b must be non-zero") from e
    else:
        # 仅 try 无异常时执行；except 不会捕获 else 里的异常
        return result
    finally:
        # 无论如何都执行，即使 try/except 里有 return
        print("finally: always runs")

# finally 陷阱：return 会吞异常
def bad_finally():
    try:
        raise ValueError("original error")
    finally:
        return "from finally"  # 静默丢弃了 ValueError!

assert bad_finally() == "from finally"  # 异常被吞掉

# === 2. except 顺序问题 ===
def match_order(n):
    try:
        if n < 0:
            raise ValueError("negative")
    except ValueError:
        print("caught ValueError")  # 子类在前，优先匹配
    except Exception:
        print("caught Exception")   # 父类兜底，放在后面

# === 3. ExceptionGroup + except*（3.11+）===
async def worker(n):
    if n == 2:
        raise ValueError(f"bad value: {n}")
    if n == 3:
        raise TypeError(f"bad type: {n}")
    await asyncio.sleep(0.01)
    return n

async def taskgroup_demo():
    try:
        async with asyncio.TaskGroup() as tg:  # 3.11+
            for i in range(5):
                tg.create_task(worker(i))
    except* ValueError as eg:
        print(f"ValueError group: {[str(e) for e in eg.exceptions]}")
    except* TypeError as eg:
        print(f"TypeError group: {[str(e) for e in eg.exceptions]}")

asyncio.run(taskgroup_demo())
